mapper.select:
SELECT capc.*, nvl(pcd.plan_cash_principal_sum,0) plan_cash_principal_sum, nvl(pcd.plan_cash_interest_sum,0) plan_cash_interest_sum, nvl(pcd.cash_principal_sum,0) cash_principal_sum, nvl(pcd.cash_interest_sum,0) cash_interest_sum, capc.due_amount-nvl(pcd.plan_cash_principal_sum,0)-nvl(pcd.plan_cash_interest_sum,0)- (nvl(capc.service_fee,0)+ nvl(capc.hosting_fee,0)+ nvl(capc.management_fee,0)+ nvl(capc.underwriting_fee,0)+ nvl(capc.rating_fee,0)+ nvl(capc.evaluation_fee,0)+ nvl(capc.listing_fee,0)+ nvl(capc.lawyer_fee,0)+ ifnull (capc.accountant_fee,0)+ nvl(capc.other_fee,0)+nvl(capc.tax_fee,0) ) surplus_amount FROM ct_abs_product_collection capc LEFT JOIN ( SELECT cd.collection_id, SUM(cd.plan_cash_principal) plan_cash_principal_sum, SUM(cd.plan_cash_interest) plan_cash_interest_sum, SUM(cd.cash_principal) cash_principal_sum, SUM(cd.cash_interest) cash_interest_sum FROM ct_abs_product_cash_detail cd GROUP BY cd.collection_id ) pcd ON pcd.collection_id=capc.collection_id WHERE 1=1
and capc.product_id = #{productId}
and capc.data_class= #{dataClass}
and capc.confirm_flag= #{confirmFlag}
ORDER BY capc.times
